#!/usr/bin/env python3
"""Validated directory fragments for canonical Orthodox bodies in Romania.

Only current bodies named by competent first-party church sources are emitted.
Aggregate-only remainders, inaccessible rosters, stale-count conflicts,
construction projects, and uncertain physical-site duplicates are retained in
``tools/directory_candidates/romania.json`` rather than inferred here.

    python tools/directory_romania.py --check
    python tools/directory_romania.py --dump
"""

import argparse
import json
from pathlib import Path
import re
import sys
import unicodedata


ROOT = Path(__file__).resolve().parent.parent
CHECKED = "2026-11-15"


def slug(value):
    value = unicodedata.normalize("NFKD", value)
    value = "".join(char for char in value if not unicodedata.combining(char))
    value = value.lower()
    value = re.sub(r"[^a-z0-9]+", "-", value).strip("-")
    return value or "body"


def row(row_id, parent, local, sources, rank="Parish", kind="parish",
        name=None, seat=None, address=None, site=None, services=None,
        founded=None):
    value = {
        "id": row_id,
        "parent": parent,
        "kind": kind,
        "rank": rank,
        "name": name or local,
        "local": local,
        "country": "RO",
        "sources": list(sources),
    }
    if seat:
        value["seat"] = seat
    if address:
        value["address"] = list(address)
    if site:
        value["site"] = site
    if services:
        value["services"] = list(services)
    if founded:
        value["founded"] = list(founded)
    return value


def deaneries(parent, source, names):
    rows = []
    for name in names:
        rows.append(row(
            "%s-deanery-%s" % (parent, slug(name)), parent,
            "Protoieria %s" % name, [source], rank="Deanery",
            name="%s Deanery" % name,
        ))
    return rows


def compact_rows(parent, source, entries):
    """Expand compact records, optionally carrying an English name."""
    rows = []
    for entry in entries:
        if len(entry) == 5:
            key, row_parent, rank, local, site = entry
            name = None
        elif len(entry) == 6:
            key, row_parent, rank, local, site, name = entry
        else:
            raise ValueError("invalid compact row: %r" % (entry,))
        kind = "monastery" if rank in {
            "Monastery", "Convent", "Skete", "Metoch",
        } else "parish"
        sources = [source]
        if site and site != source:
            sources.append(site)
        rows.append(row(
            "%s-%s" % (parent, key), row_parent, local, sources,
            rank=rank, kind=kind, site=site, name=name,
        ))
    return rows


